  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Counting Principle and Permutations$j$, $j${"readings": [{"title": "Psalm 147 (King James Version)", "url": "/portal/bible/Psalms/147"}], "body": "To find a probability we often need to count the outcomes. Psalm 147:4 says, He telleth the number of the stars; he calleth them all by their names. God counts what we cannot, and we learn smart ways to count what we can.\n\nThe fundamental counting principle says that if one choice can be made in m ways and a second choice in n ways, the two choices together can be made in m times n ways. A student has 3 shirts and 4 pairs of pants, so there are 3 times 4, or 12, outfits. A four digit code, where each digit can be 0 through 9 and digits may repeat, has 10 times 10 times 10 times 10, or 10,000, possibilities. A license tag with three letters has 26 times 26 times 26, or 17,576, possibilities.\n\nWhen order matters and no item is used twice, we count arrangements. A factorial is the product of a whole number and every positive whole number below it. We write 5 factorial as 5 followed by an exclamation point, and it equals 5 times 4 times 3 times 2 times 1, which is 120. By definition, 0 factorial equals 1. Four students can stand in a line in 4 factorial ways, which is 24.\n\nA permutation is an ordered arrangement of some items chosen from a larger group. If five people run for president, vice president and secretary, the president can be chosen 5 ways, the vice president 4 ways, and the secretary 3 ways. The number of permutations is 5 times 4 times 3, which is 60. In symbols, the number of permutations of n items taken r at a time equals n factorial divided by the factorial of n minus r. Here, 5 factorial divided by 2 factorial is 120 divided by 2, which is 60.\n\nThe key question is whether order matters. If first place, second place and third place are different honors, order matters. The word arrangement signals a permutation.\n\nYour task: (1) Use the counting principle to count outfits or codes. (2) Compute a factorial. (3) Count the permutations when 5 people compete for 3 different offices.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Psalm 147:4 says, He telleth the number of the stars; he calleth them all by their names. God counts what we cannot. We learn smart ways to count what we can.\n\nNow watch this. The fundamental counting principle says that if one choice can be made in m ways and another in n ways, together they can be made in m times n ways. Three shirts and four pairs of pants give 12 outfits. A four digit code gives 10 times 10 times 10 times 10, which is 10,000 possibilities.\n\nLook at factorials. 5 factorial is 5 times 4 times 3 times 2 times 1, which is 120. Zero factorial is defined to be 1. Four students can stand in a line in 4 factorial, or 24, ways.\n\nA permutation is an ordered arrangement of some items from a larger group. Five people run for president, vice president and secretary. The president can be chosen 5 ways, the vice president 4 ways, the secretary 3 ways. That is 5 times 4 times 3, or 60.\n\nThe key question is whether order matters. If first, second and third place are different honors, order matters, and that signals a permutation.\n\nYour task is to use the counting principle, compute a factorial and count permutations. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Counting Principle and Permutations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Combinations$j$, $j${"readings": [{"title": "Luke 6 (King James Version)", "url": "/portal/bible/Luke/6"}], "body": "Sometimes order does not matter. Luke 6:13 says, And when it was day, he called unto him his disciples: and of them he chose twelve, whom also he named apostles. The Lord chose a group of twelve from a larger group of disciples. The group itself mattered. The order in which He named them is not what defines the group.\n\nA combination is a selection of items in which order does not matter. Choosing three students for a committee gives the same committee whether we name Ann, Ben and Chris, or Chris, Ben and Ann. To count combinations, start with the number of permutations and divide by the number of ways to arrange the chosen items. The number of combinations of n items taken r at a time equals n factorial divided by the product of r factorial and the factorial of n minus r.\n\nExample: how many 3 person committees can be formed from 5 people? The permutations of 5 taken 3 at a time are 5 times 4 times 3, which is 60. Each committee of 3 can be arranged in 3 factorial, or 6, orders, so we divide: 60 divided by 6 is 10. Another example: choosing 3 people from 8 gives 8 times 7 times 6 divided by 3 times 2 times 1, which is 336 divided by 6, or 56. Choosing 2 from 10 gives 10 times 9 divided by 2, which is 45.\n\nWe can combine counting with probability. A committee of 3 is chosen at random from 5 girls and 3 boys. The total number of committees is 56. The number of committees with all girls is the number of ways to choose 3 of 5 girls, which is 10. So the probability that the committee is all girls is 10/56, or 5/28.\n\nTo decide between the two, ask whether the order changes the result. A president and vice president is a permutation. A pair of co chairs is a combination.\n\nYour task: (1) Explain the difference between a permutation and a combination. (2) Compute the number of ways to choose 3 people from 8. (3) Find the probability that a random committee is all girls.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Luke 6:13 says, And when it was day, he called unto him his disciples: and of them he chose twelve. The Lord chose a group from a larger group. The group mattered, not the order in which He named them.\n\nNow watch this. A combination is a selection in which order does not matter. A committee of Ann, Ben and Chris is the same committee as Chris, Ben and Ann. To count combinations, take the number of permutations and divide by the number of ways to arrange the chosen items.\n\nLook at an example. How many 3 person committees can we form from 5 people? The permutations are 5 times 4 times 3, which is 60. Each committee can be arranged in 3 factorial, or 6, ways, so 60 divided by 6 is 10. Choosing 3 from 8 gives 336 divided by 6, which is 56. Choosing 2 from 10 gives 45.\n\nNow combine counting with probability. A committee of 3 is chosen at random from 5 girls and 3 boys. There are 56 possible committees, and 10 of them are all girls. The probability is 10/56, or 5/28.\n\nTo decide which to use, ask whether the order changes the result. President and vice president is a permutation. Two co chairs is a combination.\n\nYour task is to explain permutation and combination, count a selection and find a probability. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Combinations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Random Variables and Expected Value$j$, $j${"readings": [{"title": "Proverbs 13 (King James Version)", "url": "/portal/bible/Proverbs/13"}], "body": "A random variable is a numerical outcome of a random process. Proverbs 13:11 says, Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase. Expected value helps us see why get rich quick plans so often fail.\n\nA discrete random variable takes a list of separate values, each with a probability. A probability distribution lists the values and their probabilities, and the probabilities add to 1. Let X be the number of heads in two tosses of a fair coin. The outcomes TT, HT, TH and HH give X equal to 0 with probability 1/4, X equal to 1 with probability 1/2, and X equal to 2 with probability 1/4.\n\nThe expected value of X is the long run average value. We find it by multiplying each value by its probability and adding the results. For the coin, the expected value is 0 times 1/4, plus 1 times 1/2, plus 2 times 1/4, which is 0 plus 1/2 plus 1/2, or 1. Over many repetitions we expect an average of 1 head per pair of tosses, even though a single pair can never show exactly the average in every case.\n\nExpected value is used in business and in fairness. Suppose a school carnival game costs 2 dollars to play. A spinner has a 1 in 5 chance of winning a 5 dollar prize and otherwise wins nothing. The expected prize is 5 times 1/5, which is 1 dollar. Because the player pays 2 dollars, the player expects to come out 1 dollar behind on average, and the school expects to raise 1 dollar per play. Such a game is fine as a fundraiser when everyone knows the rules and plays for fun. The same arithmetic shows why casinos and lotteries are designed so that players lose money over time. A sensible believer counts the cost and does not stake the family budget on a game that is built to take money.\n\nInsurance works the same way. Companies charge a little more than the expected cost of claims so that families are protected from rare large losses.\n\nYour task: (1) Build a probability distribution for a random variable. (2) Compute an expected value. (3) Explain why a game with a negative expected value for the player is a poor way to build wealth.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Proverbs 13:11 says, Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase. Expected value shows us why get rich quick plans so often fail.\n\nNow watch this. A random variable is a numerical outcome of a random process. A probability distribution lists the values and their probabilities, and the probabilities add to 1. Let X be the number of heads in two coin tosses. X is 0 with probability 1/4, 1 with probability 1/2, and 2 with probability 1/4.\n\nThe expected value is the long run average. Multiply each value by its probability and add. For the coin, 0 times 1/4, plus 1 times 1/2, plus 2 times 1/4, equals 1.\n\nLook at a carnival game. It costs 2 dollars to play. A spinner has a 1 in 5 chance of winning 5 dollars. The expected prize is 5 times 1/5, which is 1 dollar. The player pays 2 dollars, so on average the player comes out 1 dollar behind and the school raises 1 dollar per play. As a fundraiser with open rules, that is fun. But the same arithmetic shows why casinos and lotteries are built so that players lose over time. A wise believer counts the cost and does not stake the family budget on a game designed to take money.\n\nInsurance works the same way. It protects families from rare large losses.\n\nYour task is to build a distribution, compute an expected value and explain why a losing game is a poor way to build wealth. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Random Variables and Expected Value$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 The Binomial Distribution$j$, $j${"readings": [{"title": "Galatians 6 (King James Version)", "url": "/portal/bible/Galatians/6"}], "body": "Many situations repeat the same chance process again and again. Galatians 6:9 says, And let us not be weary in well doing: for in due season we shall reap, if we faint not. Repeated trials add up over time, and the binomial distribution gives the pattern for counting successes in a fixed number of repeated trials.\n\nA situation is binomial when four conditions are met. There are a fixed number of trials, which we call n. Each trial has only two outcomes, success or failure. The trials are independent. The probability of success, p, is the same on every trial.\n\nExample: a student makes 80 percent of her free throws. She shoots 3 times. Let X be the number she makes. Here n is 3 and p is 0.8, so the probability of a miss is 0.2. The probability of exactly k successes is the number of ways to choose which k trials succeed, times p to the power k, times the probability of failure to the power n minus k.\n\nTo find exactly 2 makes, there are 3 ways to choose which 2 shots go in, so the probability is 3 times 0.8 times 0.8 times 0.2, which is 3 times 0.64 times 0.2, or 0.384. Exactly 3 makes is 0.8 times 0.8 times 0.8, which is 0.512. Exactly 1 make is 3 times 0.8 times 0.2 times 0.2, which is 0.096. No makes is 0.2 times 0.2 times 0.2, which is 0.008. These four probabilities add to 1. The probability of at least 2 makes is 0.384 plus 0.512, which is 0.896.\n\nThe mean of a binomial random variable is n times p. Here it is 3 times 0.8, which is 2.4 makes per set of three shots. The standard deviation is the square root of n times p times the probability of failure.\n\nGalatians 6:7 reminds us that whatsoever a man soweth, that shall he also reap. Practice, like seed, produces a harvest over many trials.\n\nYour task: (1) Decide whether a situation is binomial and name n and p. (2) Find the probability of exactly 2 successes in 3 trials. (3) Find the mean of a binomial random variable.\n\nFlorida standards: MA.912.DP.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MA.912.DP", "script": "Welcome back. Listen, Galatians 6:9 says, And let us not be weary in well doing: for in due season we shall reap, if we faint not. Repeated trials add up over time.\n\nNow watch this. A situation is binomial when there are a fixed number of trials, each trial has two outcomes, the trials are independent, and the probability of success is the same each time.\n\nLook at an example. A student makes 80 percent of her free throws and shoots three times. Here n is 3, p is 0.8, and the chance of a miss is 0.2. For exactly 2 makes, there are 3 ways to choose which two shots go in. The probability is 3 times 0.8 times 0.8 times 0.2, which is 0.384. Exactly 3 makes is 0.512. Exactly 1 make is 0.096. No makes is 0.008. Those four add to 1. The chance of at least 2 makes is 0.384 plus 0.512, which is 0.896.\n\nThe mean of a binomial random variable is n times p. Here it is 3 times 0.8, or 2.4 makes.\n\nGalatians 6:7 says, whatsoever a man soweth, that shall he also reap. Practice, like seed, produces a harvest over many trials.\n\nYour task is to decide whether a situation is binomial, find the probability of exactly 2 successes in 3 trials and find a mean. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 The Binomial Distribution$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Counting and Random Variables$j$, $j${"prompt": "Write a report of at least 250 words on counting and random variables. Use complete sentences, show every calculation and label each part. Galatians 6:9 says, And let us not be weary in well doing: for in due season we shall reap, if we faint not.\n\nPart 1: A lunch menu offers 4 sandwiches, 3 sides and 5 drinks. Use the counting principle to find the number of different meals. Find 6 factorial.\nPart 2: Seven students compete for first, second and third place. Find the number of possible outcomes. Then explain whether choosing a team of 3 from the same 7 students is a permutation or a combination, and find the number of teams.\nPart 3: A committee of 3 is chosen at random from 4 girls and 3 boys. Find the probability that it is all boys.\nPart 4: A fundraiser game costs 3 dollars to play. A spinner wins a 10 dollar prize with probability 1/5, and otherwise wins nothing. Find the expected prize and the expected result for the player. Explain, using Proverbs 13:11, why believers should be careful with games of chance.\nPart 5: A basketball player makes 70 percent of free throws and shoots 3 times. Build the probability distribution for the number of makes and find the mean.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 15 points. Part 4: 25 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Counting and Random Variables$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Counting the Cost$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a situation from school, church or home where counting the number of choices or arrangements would help, (2) explains in your own words the difference between a permutation and a combination, (3) explains why expected value shows that games built to take money are a poor plan for building wealth, and (4) connects your answer to Proverbs 13:11, Luke 6:13 or Galatians 6:9. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How does counting the cost before we begin a project show wisdom? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Counting the Cost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Counting Principle and Permutations$j$, $j${"questions": [{"q": "A student has 3 shirts and 4 pairs of pants. The number of outfits is:", "options": ["7", "24", "1", "12"]}, {"q": "5 factorial equals:", "options": ["5", "25", "120", "60"]}, {"q": "Five candidates compete for president, vice president and secretary. The number of ways to fill the offices is:", "options": ["10", "125", "60", "15"]}, {"q": "A four digit code using digits 0 through 9 with repeats allowed has how many possibilities?", "options": ["9,999", "10,000", "5,040", "40"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Counting Principle and Permutations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,2,1}'::int[], array[$j$3 times 4 equals 12.$j$,$j$5 times 4 times 3 times 2 times 1 equals 120.$j$,$j$5 times 4 times 3 equals 60.$j$,$j$10 times 10 times 10 times 10 equals 10,000.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Counting Principle and Permutations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Combinations$j$, $j${"questions": [{"q": "A selection in which order does not matter is a:", "options": ["Factorial", "Complement", "Combination", "Permutation"]}, {"q": "The number of ways to choose 3 people from 5 is:", "options": ["5", "60", "15", "10"]}, {"q": "The number of ways to choose 2 people from 10 is:", "options": ["90", "45", "100", "20"]}, {"q": "Choosing a president and a vice president from a group is a:", "options": ["Complement", "Factorial", "Permutation", "Combination"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Combinations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,2}'::int[], array[$j$That is the definition of a combination.$j$,$j$60 divided by 6 equals 10.$j$,$j$10 times 9 divided by 2 equals 45.$j$,$j$The two offices are different, so order matters.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Combinations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Random Variables and Expected Value$j$, $j${"questions": [{"q": "The probabilities in a probability distribution add to:", "options": ["The mean", "100 dollars", "1", "0"]}, {"q": "The expected number of heads in two fair coin tosses is:", "options": ["2", "1/2", "1", "4"]}, {"q": "A game pays 5 dollars with probability 1/5 and nothing otherwise. The expected prize is:", "options": ["25 cents", "2 dollars", "1 dollar", "5 dollars"]}, {"q": "If a game costs 2 dollars and the expected prize is 1 dollar, the player on average:", "options": ["Gains 1 dollar per play", "Loses 1 dollar per play", "Breaks even", "Wins every time"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Random Variables and Expected Value$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,1}'::int[], array[$j$All outcomes together are certain.$j$,$j$0 times 1/4 plus 1 times 1/2 plus 2 times 1/4 equals 1.$j$,$j$5 times 1/5 equals 1 dollar.$j$,$j$The player expects to be 1 dollar behind.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Random Variables and Expected Value$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: The Binomial Distribution$j$, $j${"questions": [{"q": "Which is NOT a condition for a binomial situation?", "options": ["Two outcomes per trial", "The probability of success changes each trial", "Independent trials", "A fixed number of trials"]}, {"q": "A shooter makes 80 percent of free throws. The mean number of makes in 3 shots is:", "options": ["1.6", "3", "2.4", "0.8"]}, {"q": "The probability of exactly 2 makes in 3 shots at 80 percent is:", "options": ["0.512", "0.384", "0.64", "0.096"]}, {"q": "The probability of making all 3 shots at 80 percent is:", "options": ["0.8", "0.512", "0.24", "0.384"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Binomial Distribution$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,1}'::int[], array[$j$The success probability must stay the same.$j$,$j$n times p equals 3 times 0.8.$j$,$j$3 times 0.64 times 0.2 equals 0.384.$j$,$j$0.8 times 0.8 times 0.8 equals 0.512.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: The Binomial Distribution$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Counting and Random Variables$j$, $j${"questions": [{"q": "The counting principle says two choices with m and n options can be made in:", "options": ["m times n ways", "m minus n ways", "m plus n ways", "m divided by n ways"]}, {"q": "4 factorial equals:", "options": ["12", "10", "24", "16"]}, {"q": "The number of ways to award first, second and third place among 5 runners is:", "options": ["125", "10", "15", "60"]}, {"q": "The number of ways to choose 3 members from a group of 8 is:", "options": ["11", "336", "24", "56"]}, {"q": "The expected value of a random variable is its:", "options": ["Long run average", "Smallest value", "Standard deviation", "Most unlikely value"]}, {"q": "A spinner pays 5 dollars with probability 1/5 and costs 2 dollars to play. The expected result for the player is:", "options": ["A loss of 1 dollar", "A gain of 1 dollar", "A gain of 3 dollars", "Zero"]}, {"q": "A binomial situation requires that trials be:", "options": ["Unlimited", "Without outcomes", "Dependent", "Independent"]}, {"q": "The mean number of successes in 10 trials with p equal to 0.3 is:", "options": ["10", "7", "3", "0.3"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Counting and Random Variables$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3,0,0,3,2}'::int[], array[$j$Multiply the number of options.$j$,$j$4 times 3 times 2 times 1 equals 24.$j$,$j$5 times 4 times 3 equals 60.$j$,$j$336 divided by 6 equals 56.$j$,$j$Expected value is the long run mean.$j$,$j$The expected prize is 1 dollar, and the player pays 2 dollars.$j$,$j$Independence is one of the four conditions.$j$,$j$n times p equals 10 times 0.3.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Counting and Random Variables$j$ on conflict (item_id) do nothing;
